import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"54、【归妹】 兑下震上","description":"温公易说 - 54、【归妹】 兑下震上","frontmatter":{"title":"54、【归妹】 兑下震上","description":"温公易说 - 54、【归妹】 兑下震上"},"headers":[],"relativePath":"zh/classics/wengong/055.md","filePath":"zh/classics/wengong/055.md"}'),n={name:"zh/classics/wengong/055.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_54、【归妹】-兑下震上" tabindex="-1">54、【归妹】 兑下震上 <a class="header-anchor" href="#_54、【归妹】-兑下震上" aria-label="Permalink to “54、【归妹】 兑下震上”">​</a></h1><h3 id="彖曰-归妹-天地之大义也。天地不交而万物不兴-归妹人之终始也。说以动-所归妹也。征凶-位不当也。无攸利-柔乘刚也。" tabindex="-1">彖曰：归妹，天地之大义也。天地不交而万物不兴，归妹人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。 <a class="header-anchor" href="#彖曰-归妹-天地之大义也。天地不交而万物不兴-归妹人之终始也。说以动-所归妹也。征凶-位不当也。无攸利-柔乘刚也。" aria-label="Permalink to “彖曰：归妹，天地之大义也。天地不交而万物不兴，归妹人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。”">​</a></h3><h3 id="象曰-泽上有雷-归妹。君子以永终知敝。" tabindex="-1">象曰：泽上有雷，归妹。君子以永终知敝。 <a class="header-anchor" href="#象曰-泽上有雷-归妹。君子以永终知敝。" aria-label="Permalink to “象曰：泽上有雷，归妹。君子以永终知敝。”">​</a></h3><h3 id="初九-归妹以娣-跛能履-征吉-象曰-归妹以娣-以恒也。跛能履-吉-相承也。" tabindex="-1">初九：归妹以娣，跛能履，征吉 象曰：归妹以娣，以恒也。跛能履，吉，相承也。 <a class="header-anchor" href="#初九-归妹以娣-跛能履-征吉-象曰-归妹以娣-以恒也。跛能履-吉-相承也。" aria-label="Permalink to “初九：归妹以娣，跛能履，征吉 象曰：归妹以娣，以恒也。跛能履，吉，相承也。”">​</a></h3><p>不正而合，是以跛也。</p><h3 id="九二-眇能视-利幽人之贞-象曰-利幽人之贞-未变常也。" tabindex="-1">九二：眇能视，利幽人之贞 象曰：利幽人之贞，未变常也。 <a class="header-anchor" href="#九二-眇能视-利幽人之贞-象曰-利幽人之贞-未变常也。" aria-label="Permalink to “九二：眇能视，利幽人之贞 象曰：利幽人之贞，未变常也。”">​</a></h3><h3 id="六三-归妹以须-反归以娣-象曰-归妹以须-未当也。" tabindex="-1">六三：归妹以须，反归以娣 象曰：归妹以须，未当也。 <a class="header-anchor" href="#六三-归妹以须-反归以娣-象曰-归妹以须-未当也。" aria-label="Permalink to “六三：归妹以须，反归以娣 象曰：归妹以须，未当也。”">​</a></h3><h3 id="九四-归妹愆期-迟归有时-象曰-愆期之志-有待而行也。" tabindex="-1">九四：归妹愆期，迟归有时 象曰：愆期之志，有待而行也。 <a class="header-anchor" href="#九四-归妹愆期-迟归有时-象曰-愆期之志-有待而行也。" aria-label="Permalink to “九四：归妹愆期，迟归有时 象曰：愆期之志，有待而行也。”">​</a></h3><h3 id="六五-帝乙归妹-其君之袂不如其娣之袂良-月几望-吉-象曰-帝乙归妹-不如其娣之袂良也。其位在中-以贵行也。" tabindex="-1">六五：帝乙归妹，其君之袂不如其娣之袂良，月几望，吉 象曰：帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。 <a class="header-anchor" href="#六五-帝乙归妹-其君之袂不如其娣之袂良-月几望-吉-象曰-帝乙归妹-不如其娣之袂良也。其位在中-以贵行也。" aria-label="Permalink to “六五：帝乙归妹，其君之袂不如其娣之袂良，月几望，吉 象曰：帝乙归妹，不如其娣之袂良也。其位在中，以贵行也。”">​</a></h3><h3 id="上六-女承筐-无实-士刲羊无血-无攸利-象曰-上六无实-承虚筐也。" tabindex="-1">上六：女承筐，无实，士刲羊无血，无攸利 象曰：上六无实，承虚筐也。 <a class="header-anchor" href="#上六-女承筐-无实-士刲羊无血-无攸利-象曰-上六无实-承虚筐也。" aria-label="Permalink to “上六：女承筐，无实，士刲羊无血，无攸利 象曰：上六无实，承虚筐也。”">​</a></h3>',10)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
